package com.fitfinance.controller;
import com.fitfinance.dto.EntryDtos.EntryResponse;import com.fitfinance.entity.Entry;import com.fitfinance.repository.EntryRepository;import org.springframework.security.core.Authentication;import org.springframework.web.bind.annotation.*;import java.time.YearMonth;import java.util.*;
@RestController @RequestMapping("/api/budget") public class BudgetController {private final EntryRepository entries;public BudgetController(EntryRepository entries){this.entries=entries;}
 @GetMapping public Optional<EntryResponse> get(@RequestParam(required=false)Integer month,@RequestParam(required=false)Integer year,Authentication auth){YearMonth requested=month==null||year==null?YearMonth.now():YearMonth.of(year,month);Long uid=(Long)auth.getPrincipal();return entries.findByUserIdAndKindOrderByEntryDateDesc(uid,"budget").stream().filter(e->YearMonth.from(e.getEntryDate()).equals(requested)).findFirst().map(BudgetController::view);}
 private static EntryResponse view(Entry e){return new EntryResponse(e.getId(),e.getKind(),e.getTitle(),e.getAmount(),e.getCategory(),e.getEntryDate(),e.getDescription(),e.getDurationMinutes(),e.getCaloriesBurned(),e.getWeight(),e.getSteps(),e.getCalories(),e.getTargetValue(),e.getCurrentValue(),e.getUnit(),e.getDeadline(),e.getStatus());}}
